create table attendance
(
    check_in_time  datetime(6)                                                                        null,
    check_out_time datetime(6)                                                                        null,
    created_at     datetime(6)                                                                        not null,
    created_by     bigint                                                                             null,
    employee_id    bigint                                                                             null,
    id             bigint                                                                             not null
        primary key,
    updated_at     datetime(6)                                                                        null,
    updated_by     bigint                                                                             null,
    note           text                                                                               null,
    status         enum ('ABSENT', 'CANCELLED', 'HALF_DAY', 'INVALID', 'LATE', 'ON_LEAVE', 'PRESENT') null,
    constraint FKr7q0h8jfngkyybll6o9r3h9ua
        foreign key (employee_id) references employee (user_id)
);

